{
  "steps": [
    {
      "id": 1,
      "claim": "The hospital has a total capacity of 1000 beds.",
      "evidence": "Given explicitly in the problem statement.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Initially 1/5 of the beds are occupied, i.e., 200 beds.",
      "evidence": "1/5 × 1000 = 200.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Initially there are 800 unoccupied beds.",
      "evidence": "1000 – 200 = 800.",
      "weight": 0.05,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Two weeks equal 14 days.",
      "evidence": "2 weeks × 7 days/week = 14 days.",
      "weight": 0.05,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "A total of 700 patients are admitted over the 14‑day period.",
      "evidence": "50 patients/day × 14 days = 700 patients.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "No patients are discharged during the two‑week period, so all admissions remain in beds.",
      "evidence": "The problem only provides an admission rate and gives no information about discharges; standard word‑problem convention treats the given rate as a net increase unless otherwise stated.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 7,
      "claim": "After two weeks, 900 beds are occupied.",
      "evidence": "Initial occupied (200) + new admissions (700) = 900.",
      "weight": 0.20,
      "depends_on": [2, 5, 6]
    },
    {
      "id": 8,
      "claim": "After two weeks, 100 beds remain unoccupied.",
      "evidence": "Total capacity (1000) – occupied beds (900) = 100.",
      "weight": 0.30,
      "depends_on": [1, 7]
    }
  ],
  "answer": "100",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "0",
      "reason_rejected": "Would require the hospital to become fully occupied, but the calculated occupancy (900) is below capacity; the problem gives no indication that all beds are filled."
    },
    {
      "answer": "800",
      "reason_rejected": "Represents the initial number of unoccupied beds and ignores the 700 new admissions that occur over the two‑week period."
    }
  ]
}
